using Boll.Core.Content;

namespace Boll.App
{
    /// <summary>Правила видов для экрана «Правила» (утверждает заказчик, CONCEPT §3).</summary>
    public static class RulesText
    {
        const string Common =
            "\n\nОбщее. Касание битком стенки, бампера или движущегося объекта до прицельного шара — не фол. Если нужно касание борта, стенка, бампер или движущийся объект его заменяют. Шар забит, когда его центр упал в лузу. Право разбоя — по жребию. Ничьих нет.";

        const string Controls =
            "\n\nУправление. Ведите палец вокруг битка — кий повернётся (чем дальше от битка, тем точнее). Оттяните палец от битка вдоль кия — это сила (полная на расстоянии 150 dp); отпустили палец — удар. Вернули палец ближе 48 dp к битку и отпустили — удар отменён. Другой способ: задайте силу ползунком справа и нажмите «Удар». Точка удара (накат, оттяжка, боковой винт) — в окне справа внизу.";

        public static string For(GameKind k)
        {
            switch (k)
            {
                case GameKind.Eight:
                    return "«Восьмёрка» (правила WPA)\n\nКОГДА ЗАКАНЧИВАЕТСЯ ИГРА\nПобеда: «8» забита в выбранную лузу после очистки своей группы, без фола. Поражение: «8» забита раньше времени, не в ту лузу или с фолом. Перед ударом по «8» касанием выберите лузу.\n\nПО КАКИМ ШАРАМ БИТЬ\nСтол открыт до первого законно забитого шара: за игроком закрепляется группа этого шара (сплошные 1–7 или полосатые 9–15), за соперником — другая. Бить нужно по шарам своей группы (они подсвечены), когда они кончились — по «8».\n\nФОЛЫ\nБиток никого не коснулся; первым задет не прицельный шар; после касания ничего не забито и никто не дошёл до борта; биток забит. После фола соперник ставит биток с руки.\n\nОСТАЛЬНОЕ\n15 шаров и биток. «8» — в центре третьего ряда треугольника. Разбой с руки из дома. Разбой законный, если забит шар или не меньше 4 шаров с номерами коснулись борта; иначе перерасстановка, разбивает соперник. «8» на разбое без фола — перерасстановка, разбивает тот же игрок. Счёт — число забитых шаров своей группы." + Common + Controls;
                case GameKind.Nine:
                    return "«Девятка» (правила WPA)\n\nКОГДА ЗАКАНЧИВАЕТСЯ ИГРА\nПобеда — «9», забитая без фола (в том числе на разбое). «9», забитая с фолом, возвращается на вершину. Три фола подряд — поражение, после второго будет предупреждение.\n\nПО КАКИМ ШАРАМ БИТЬ\nПервым нужно тронуть шар с наименьшим номером (он подсвечен). Забили без фола — бьёте дальше.\n\nФОЛЫ\nБиток никого не коснулся; первым задет не тот шар; после касания ничего не забито и никто не дошёл до борта; биток забит. После фола соперник ставит биток с руки.\n\nОСТАЛЬНОЕ\nШары 1–9 ромбом: «1» в вершине, «9» в центре. Разбой с руки из дома: первым нужно тронуть «1» и забить шар или довести 4 шара до борта, иначе фол. Счёт — число шаров, забитых своими ударами." + Common + Controls;
                case GameKind.American:
                    return "«Американка» (русская пирамида)\n\nКОГДА ЗАКАНЧИВАЕТСЯ ИГРА\nПобеда — 8 очков.\n\nПО КАКИМ ШАРАМ БИТЬ\nБить можно любым шаром: перед каждым ударом коснитесь шара, которым будете бить (он выделен кольцом), остальные шары — прицельные.\n\nФОЛЫ\nБиток никого не коснулся; биток забит без контакта; если ничего не забито — ни один шар после контакта не коснулся двух разных бортов и не пересёк центральную линию с касанием борта. Фол: шары удара возвращаются на заднюю отметку без очков, нарушитель возвращает один свой шар и теряет очко. Ход переходит к сопернику с текущей позиции.\n\nОСТАЛЬНОЕ\n15 белых шаров и один цветной. Разбой цветным шаром из дома. Очко — за каждый шар, забитый после контакта, и за биток, упавший после контакта. Шар, упавший до касания битка (столкнул движущийся объект), очков не даёт и возвращается." + Common + Controls;
                case GameKind.Siberian:
                    return "«Сибирка» (московская пирамида)\n\nКОГДА ЗАКАНЧИВАЕТСЯ ИГРА\nПобеда — 8 очков.\n\nПО КАКИМ ШАРАМ БИТЬ\nБьют только цветным битком, прицельные шары — белые (они подсвечены).\n\nФОЛЫ\nКак в «Американке». Удар из дома, где биток первым коснулся шара в доме, — фол. Белые шары удара возвращаются, нарушитель отдаёт белый шар с наименьшим номером и теряет очко. Ход сопернику: с руки из дома, если биток забит, иначе с места остановки битка.\n\nОСТАЛЬНОЕ\nБиток, упавший после контакта, приносит очко, и следующий удар тот же игрок делает с руки из дома — по шару за линией дома. Если за линией дома нет белых шаров, ближайший к линии белый шар ставится на заднюю отметку. Остальное — как в «Американке»." + Common + Controls;
                default:
                    return "Снукер (правила WPBSA)\n\nКОГДА ЗАКАНЧИВАЕТСЯ ИГРА\nОдин фрейм. Он кончается, когда последний чёрный шар забит или сыгран с фолом как последний шар на столе. Побеждает набравший больше очков. При равенстве чёрный возвращается на место и разыгрывается: кто следующим забьёт шар или получит фол, тот и решает исход.\n\nПО КАКИМ ШАРАМ БИТЬ\nОчередь: красный, затем цветной (выберите его кнопкой перед ударом), потом снова красный (подсвечены шары, по которым можно бить). Когда красные кончились — цветные по возрастанию: жёлтый 2, зелёный 3, коричневый 4, синий 5, розовый 6, чёрный 7.\n\nФОЛЫ\nПервым тронут неразрешённый шар — фол по WPBSA. Промах — не фол. Биток никого не коснулся — не фол, ход соперника без штрафа (если биток в лузе — с руки в зоне D).\n\nОСТАЛЬНОЕ\nСвободный шар и возврат цветных на отметки — по WPBSA; кнопка «Свободный шар» появляется после фола, если биток в снукере." + Common + Controls;
            }
        }
    }
}
